results.content:
        over_per_kg=int(spec.get("over_per_kg_cents", 0)),
        zones=zones,
        fuel=_decimal(spec.get("fuel_pct", 0), "fuel_pct"),
    )


def table(spec: dict) -> RateTable:
    """The parsed table for spec; each distinct table is parsed once (rates.md 4)."""
    if not isinstance(spec, dict) or not all(k in spec for k in ("carrier", "service", "effective")):
        raise RateError("a rate table needs carrier, service and effective")
    try:
        key = json.dumps(spec, sort_keys=True, allow_nan=False)
    except (TypeError, ValueError):
        raise RateError("a rate table must be plain JSON") from None
    with _lock:
        cached = _tables.get(key)
        if cached is not None:
            _stats["hits"] += 1
            return cached
        _stats["misses"] += 1
        parsed = parse(spec)
